WITH _hq_raw AS (SELECT tuple(analytics.orders.created_at, analytics.orders.status, analytics.orders.amount_cents, NULL, analytics.orders.customer_id, NULL) AS _hq_row FROM analytics.orders WHERE analytics.orders.tenant_id = ?),
_hq_source AS (SELECT toDateTime64(assumeNotNull(tupleElement(_hq_row, 1)), 9, 'UTC') AS _hq_time, tupleElement(_hq_row, 2) AS _hq_d0, tupleElement(_hq_row, 3) AS _hq_v0, tupleElement(_hq_row, 4) AS _hq_a0, tupleElement(_hq_row, 5) AS _hq_v1, tupleElement(_hq_row, 6) AS _hq_a1 FROM _hq_raw WHERE isNotNull(tupleElement(_hq_row, 1))),
_hq_bounds AS (SELECT parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_lower, parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_upper, toStartOfDay(_hq_lower) AS _hq_first, toStartOfDay(_hq_upper) AS _hq_last),
_hq_series AS (SELECT addDays(_hq_first, arrayJoin(range(toUInt64(dateDiff('day', _hq_first, _hq_last) + 1 + 0 + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_first, _hq_calendar_index + 1) <= addDays(_hq_first, _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', _hq_first, _hq_last) + 1 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.') + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))) AS _hq_period FROM _hq_bounds),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time >= _hq_first AND _hq_time < addDays(_hq_last, 1)) OR (_hq_time < addDays(_hq_last, 1) AND _hq_time >= least(subtractDays(addDays(_hq_first, 1), 7), subtractDays(addDays(_hq_first, 1), 14), toStartOfMonth(_hq_first)))),
_hq_skeleton AS (SELECT * FROM _hq_series CROSS JOIN (SELECT DISTINCT _hq_d0 FROM _hq_scanned) AS _hq_combinations),
_hq_fan0 AS (SELECT *, toStartOfDay(_hq_time) AS _hq_period FROM _hq_scanned WHERE _hq_time >= _hq_lower AND _hq_time <= _hq_upper),
_hq_agg0 AS (SELECT _hq_period, _hq_d0, toNullable(sumOrNull(_hq_v0)) AS _hq_m0 FROM _hq_fan0 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period, _hq_d0),
_hq_fan1 AS (SELECT *, addDays(toStartOfDay(_hq_time), arrayJoin(range(toUInt64(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) > 1000, 'A window row contributes to more than 1000 buckets.') + throwIf(arrayExists(_hq_calendar_index -> addDays(toStartOfDay(_hq_time), _hq_calendar_index + 1) <= addDays(toStartOfDay(_hq_time), _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) > 1000, 'A window row contributes to more than 1000 buckets.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.'))))) AS _hq_period FROM _hq_scanned),
_hq_agg1 AS (SELECT _hq_period, _hq_d0, toNullable(sumOrNull(_hq_v0)) AS _hq_m1 FROM _hq_fan1 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= subtractDays(addDays(_hq_period, 1), 7) GROUP BY _hq_period, _hq_d0),
_hq_fan2 AS (SELECT *, addDays(toStartOfDay(_hq_time), arrayJoin(range(toUInt64(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 14)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 14)) > 1000, 'A window row contributes to more than 1000 buckets.') + throwIf(arrayExists(_hq_calendar_index -> addDays(toStartOfDay(_hq_time), _hq_calendar_index + 1) <= addDays(toStartOfDay(_hq_time), _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 14)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 14)) > 1000, 'A window row contributes to more than 1000 buckets.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.'))))) AS _hq_period FROM _hq_scanned),
_hq_agg2 AS (SELECT _hq_period, _hq_d0, toNullable(uniqExact(_hq_v1)) AS _hq_m2 FROM _hq_fan2 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= subtractDays(addDays(_hq_period, 1), 14) GROUP BY _hq_period, _hq_d0),
_hq_fan3 AS (SELECT *, addDays(toStartOfDay(_hq_time), arrayJoin(range(toUInt64(dateDiff('day', toStartOfDay(_hq_time), addMonths(toStartOfMonth(_hq_time), 1)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addMonths(toStartOfMonth(_hq_time), 1)) > 1000, 'A window row contributes to more than 1000 buckets.') + throwIf(arrayExists(_hq_calendar_index -> addDays(toStartOfDay(_hq_time), _hq_calendar_index + 1) <= addDays(toStartOfDay(_hq_time), _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', toStartOfDay(_hq_time), addMonths(toStartOfMonth(_hq_time), 1)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addMonths(toStartOfMonth(_hq_time), 1)) > 1000, 'A window row contributes to more than 1000 buckets.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.'))))) AS _hq_period FROM _hq_scanned),
_hq_agg3 AS (SELECT _hq_period, _hq_d0, toNullable(sumOrNull(_hq_v0)) AS _hq_m3 FROM _hq_fan3 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period, _hq_d0),
_hq_values AS (SELECT s._hq_period AS period, s._hq_d0 AS `status`, m0._hq_m0 AS `revenue`, m1._hq_m1 AS `rolling`, coalesce(m2._hq_m2, 0) AS `rollingBuyers`, m3._hq_m3 AS `monthToDate` FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period AND isNotDistinctFrom(s._hq_d0, m0._hq_d0) LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period AND isNotDistinctFrom(s._hq_d0, m1._hq_d0) LEFT JOIN _hq_agg2 AS m2 ON s._hq_period = m2._hq_period AND isNotDistinctFrom(s._hq_d0, m2._hq_d0) LEFT JOIN _hq_agg3 AS m3 ON s._hq_period = m3._hq_period AND isNotDistinctFrom(s._hq_d0, m3._hq_d0)),
_hq_result AS (SELECT `period`, `status`, `revenue`, `rolling`, `rollingBuyers`, `monthToDate` FROM _hq_values UNION ALL SELECT NULL AS `period`, NULL AS `status`, NULL AS `revenue`, NULL AS `rolling`, NULL AS `rollingBuyers`, NULL AS `monthToDate` FROM _hq_bounds WHERE 0 + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_first, _hq_calendar_index + 1) <= addDays(_hq_first, _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', _hq_first, _hq_last) + 1 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.') + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.') + 0 = 1) SELECT `period`, `status`, `revenue`, `rolling`, `rollingBuyers`, `monthToDate` FROM _hq_result ORDER BY `period` ASC

